def investigate(context, acquire):
    history = acquire("history")

    def simulate(actions, channel_mode):
        committed = {}
        conns = {'main': {'txn': False, 'pending': {}}, 'other': {'txn': False, 'pending': {}}}
        total = {'main': 0, 'other': 0}

        def get_view(conn):
            view = dict(committed)
            for k, v in conns[conn]['pending'].items():
                if v is None:
                    view.pop(k, None)
                else:
                    view[k] = v
            return view

        for act in actions:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'begin':
                conns[conn]['txn'] = True
                conns[conn]['pending'] = {}
            elif op == 'commit':
                for k, v in conns[conn]['pending'].items():
                    if v is None:
                        committed.pop(k, None)
                    else:
                        committed[k] = v
                conns[conn]['txn'] = False
                conns[conn]['pending'] = {}
            elif op == 'rollback':
                conns[conn]['txn'] = False
                conns[conn]['pending'] = {}
            elif op == 'put':
                key = act['key']
                val = act['value']
                view = get_view(conn)
                if key not in view:
                    if conns[conn]['txn']:
                        conns[conn]['pending'][key] = val
                    else:
                        committed[key] = val
                    total[conn] += 2
            elif op == 'update':
                key = act['key']
                val = act['value']
                view = get_view(conn)
                if key in view:
                    if conns[conn]['txn']:
                        conns[conn]['pending'][key] = val
                    else:
                        committed[key] = val
                    total[conn] += 1
            elif op == 'delete':
                key = act['key']
                view = get_view(conn)
                if key in view:
                    if conns[conn]['txn']:
                        conns[conn]['pending'][key] = None
                    else:
                        committed.pop(key, None)
                    total[conn] += 1

        if channel_mode == 'main':
            ch = total['main']
        else:
            ch = total['main'] + total['other']
        return ch, len(committed), sum(committed.values())

    actions = context.get('actions', [])
    goal = context.get('goal')

    ch_main, cnt_main, sm_main = simulate(actions, 'main')
    ch_both, cnt_both, sm_both = simulate(actions, 'both')

    if goal == 'channel':
        if ch_main == ch_both:
            return {'value': ch_main, 'unresolved': False}
        return {'value': None, 'unresolved': True}
    if goal == 'committed_count':
        if cnt_main == cnt_both:
            return {'value': cnt_main, 'unresolved': False}
        return {'value': None, 'unresolved': True}
    if goal == 'committed_sum':
        if sm_main == sm_both:
            return {'value': sm_main, 'unresolved': False}
        return {'value': None, 'unresolved': True}
    return {'value': None, 'unresolved': True}
